using System.Security.Claims;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_98fa0472e4904f7bba9ef2cc1d4388f5.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that returns a hardcoded
/// authenticated user with the configured claims.
/// </summary>
public sealed class HardcodedAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> _state;

    static HardcodedAuthenticationStateProvider()
    {
        var claims = new[]
        {
            new Claim(ClaimTypes.Name,  "bob@example.com"),
            new Claim(ClaimTypes.Email, "bob@example.com"),
            new Claim(ClaimTypes.Role,  "User"),
            new Claim(ClaimTypes.Role,  "Editor"),
        };

        var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
        _state = Task.FromResult(new AuthenticationState(new ClaimsPrincipal(identity)));
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _state;
}

