using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;
using sv_98fa0472e4904f7bba9ef2cc1d4388f5.Client;
using System.Security.Claims;

namespace sv_98fa0472e4904f7bba9ef2cc1d4388f5.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that returns a hardcoded user
/// and persists the identity into PersistentComponentState so the client
/// can reconstruct it after the WebAssembly runtime takes over.
/// </summary>
public sealed class ServerAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
{
    private static readonly AuthenticationState _state;
    private readonly PersistentComponentState _persistentState;
    private PersistingComponentStateSubscription _subscription;

    static ServerAuthenticationStateProvider()
    {
        var claims = new[]
        {
            new Claim(ClaimTypes.Name,  "bob@example.com"),
            new Claim(ClaimTypes.Email, "bob@example.com"),
            new Claim(ClaimTypes.Role,  "User"),
            new Claim(ClaimTypes.Role,  "Editor"),
        };

        var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
        _state = new AuthenticationState(new ClaimsPrincipal(identity));
    }

    public ServerAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        _persistentState = persistentState;
        _subscription = persistentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
        => Task.FromResult(_state);

    private Task OnPersistingAsync()
    {
        var principal = _state.User;
        var email = principal.FindFirst(ClaimTypes.Email)?.Value ?? principal.Identity?.Name ?? "";
        var roles = principal.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray();

        _persistentState.PersistAsJson(nameof(UserInfo), new UserInfo
        {
            Email = email,
            Roles = roles,
        });

        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

